: null}, "popularity": 0.7, "visual_tags": [{"tags": ["exterior", "panoramic", "ground_level", "sunny", "park", "cityscape", "blooming_flowers", "spring_greenery", "empty", "crowded", "unknown_country"], "season": "spring", "evidence": {}, "confidence": 0.7, "tag_source": "gpt_4o_mini_image_history"}], "name_primary": "Jardin des Plantes", "viewpoint_id": 69021, "category_norm": "attraction", "name_variants": {}, "historical_summary": null, "historical_evidence": []}, "arguments": {"viewpoint_id": 69021}}, {"tool": "get_viewpoint_details", "result": {"wikidata": {"qid": "Q31507187", "claims": {"P18": [{"label": "main image", "value": "File:三春滝桜_(Miharu_Takizakura).jpg"}], "P31": [{"label": "tourist attraction", "value": "Q570116"}]}, "wikidata_qid": "Q31507187", "sitelinks_count": 19}, "wikipedia": {"lang": "en", "title": "三春滝桜_(Miharu_Takizakura)", "extract": null, "sections": [], "citations": [{"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref3", "url": "https://whc.unesco.org", "text": "UNESCO World Heritage documentation"}, {"ref": "ref1", "url": "https://example.com/tourism", "text": "Official tourism website"}], "extract_text": null}, "popularity": 0.7, "visual_tags": [{"tags": ["exterior", "panoramic", "spring_greenery", "blooming_flowers", "cherry_blossom", "unknown_country"], "season": "unknown", "evidence": {}, "confidence": 0.0, "tag_source": "gpt_4o_mini_image_history"}], "name_primary": "三春滝桜 (Miharu Takizakura)", "viewpoint_id": 70049, "category_norm": "attraction", "name_variants": {"name:en": "Miharu Takizakura", "name:ja": "三春滝桜", "name:zh": "三春泷樱"}, "historical_summary": null, "historical_evidence": []}, "arguments": {"viewpoint_id": 70049}}, {"tool": "get_viewpoint_details", "result": {"wikidata": {"qid": "Q853638512", "claims": {"P18": [{"label": "main image", "value": "File:バンデット.jpg"}], "P31": [{"label": "tourist attraction", "value": "Q570116"}]}, "wikidata_qid": "Q853638512", "sitelinks_count": 30}, "wikipedia": {"lang": "en", "title": "バンデット", "extract": "Bandit  is a steel roller coaster located at Yomiuriland in the city of Inagi, near Tokyo, Japan. Built in 1988 by the TOGO company, it was the fastest roller coaster in the world when it was built. It lost the record to Magnum XL-200 at Cedar Point one year later.", "sections": [{"index": "1", "level": 1, "title": "Ride layout and experience", "content": "Ride layout and experience[edit] Bandit lift hill Bandit''s course is laid out as a terrain roller coaster. This means that it was custom-built to closely follow the contours of the hilly topography of Yomiuriland. Although the coaster''s height is officially listed at 167.3 feet (51.0&#160;m), the layout of the terrain means that the difference between the highest and lowest points on the ride is actually 256 feet (78&#160;m) (also a record when it was built).&#91;1&#93; When Bandit was built in 1988, it held the record of being the fastest roller coaster in the world.&#91;2&#93;&#91;3&#93; The ride passes through the treetops of hundreds of cherry trees. This is highlighted during the park''s annual cherry blossom (sakura) festival. During the festival, Bandit is marketed as being the fastest ever \"flower viewing\" (hanami). The cherry blossoms around Bandit''s course are also lit at night.&#91;4&#93; The majority of Bandit''s course is somewhat isolated from the other rides and buildings in Yomiuriland.&#91;5&#93; From the top of Bandit, riders can see views of the distant Shinjuku skyline of Tokyo.&#91;5&#93;&#91;6&#93; Rides on the coaster cost 1000 yen.&#91;6&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-