INSERT INTO query_log (id, user_text, user_images, query_intent, sql_queries, tool_calls, results, execution_time_ms, created_at) VALUES (22, '中国的湿地', '[]'::jsonb, '{"geo_hints": {"country": "中国", "place_name": "中国"}, "query_tags": ["park"], "scene_hints": [], "season_hint": "unknown", "name_candidates": [], "confidence_notes": []}'::jsonb, '[{"sql": "\n            SELECT \n                e.viewpoint_id,\n                e.name_primary,\n                e.name_variants,\n                e.category_norm,\n                e.popularity,\n                0.0 as name_score,\n                CASE WHEN (vca.viewpoint_country ILIKE %s OR vca.viewpoint_country ILIKE %s OR vca.viewpoint_country ILIKE %s OR vca.viewpoint_country ILIKE %s) THEN 1.0 ELSE 0.0 END as geo_score,\n                CASE WHEN e.category_norm = %s THEN 1.0 ELSE 0.0 END as category_score\n            FROM viewpoint_entity e\n            INNER JOIN viewpoint_commons_assets vca ON e.viewpoint_id = vca.viewpoint_id\n            WHERE e.category_norm = %s\n              AND vca.viewpoint_country IS NOT NULL\n              AND (vca.viewpoint_country ILIKE %s OR vca.viewpoint_country ILIKE %s OR vca.viewpoint_country ILIKE %s OR vca.viewpoint_country ILIKE %s)\n            ORDER BY geo_score DESC, e.popularity DESC NULLS LAST\n            LIMIT %s\n            ", "params": ["%China%", "%China%", "%People''s Republic of China%", "%PRC%", "park", "park", "%China%", "%China%", "%People''s Republic of China%", "%PRC%", 50]}]'::jsonb, '[{"tool": "extract_query_intent", "result": {"query_intent": {"geo_hints": {"country": "中国", "place_name": "中国"}, "query_tags": ["park"], "scene_hints": [], "season_hint": "unknown", "name_candidates": [], "confidence_notes": []}, "tag_schema_version": "v1.0.0"}, "arguments": {"language": "zh", "user_text": "中国的湿地"}}, {"tool": "search_by_category", "result": {"sql": "\n            SELECT \n                e.viewpoint_id,\n                e.name_primary,\n                e.name_varia